export function maximumFrequencyStack(operations: (string|number)[][]): (number|null)[] {
const freq=new Map<number,number>(),groups=new Map<number,number[]>();let max=0;return operations.map(op=>{if(op[0]==='push'){const v=Number(op[1]),f=(freq.get(v)??0)+1;freq.set(v,f);if(!groups.has(f))groups.set(f,[]);groups.get(f)!.push(v);max=Math.max(max,f);return null;}const group=groups.get(max)!,v=group.pop()!;freq.set(v,freq.get(v)!-1);if(!group.length)max--;return v;});
}
